  IF (NEW.c2 IS NULL AND NEW.c5 IS NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c5 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c5 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c5 IS NULL AND c2 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c5 IS NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k2 violated'; END IF;
